sys_script_client.script:
function onSubmit() {
    var managerID = g_form.getValue('manager'); // Pega o sys_id do manager
    var baseName = g_form.getValue('name'); // Pega o nome da base diretamente

    if (managerID) {
        g_form.getReference('manager', function(managerRecord) {
            if (managerRecord) {
                var managerName = managerRecord.name; // Obtém o nome do usuário
                executarScriptInclude(managerName, baseName);
            }
        });


    }
}

function executarScriptInclude(managerName, baseName) {
    if (!managerName || !baseName) {
        g_form.addErrorMessage('Erro: Manager ou Base não informados corretamente.');
        return;
    }

    var ga = new GlideAjax('BaseManagerHandler');
    ga.addParam('sysparm_name', managerName);
    ga.addParam('sysparm_base', baseName);
    ga.getXMLAnswer(function(response) {

        if (response.startsWith('Erro')) {
            g_form.addErrorMessage(response);
        } else {
            g_form.addInfoMessage(response);
        }
    });
}
